/**
 * The generated starter site, captured from a real Groq run on 2026-08-27.
 *
 * Seeded for the same reason the analysis and concept are: the daily model
 * quota is shared with whoever is evaluating this, and a demo account that
 * needs a working quota to show its headline feature is not insurance. This
 * costs zero model calls to restore.
 */
export const DEMO_GENERATED_HTML: string = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>Soloist – Artisanal Issue Tracker for Solo Developers</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Instrument+Serif:wght@400;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --ink:#1C1C1C;\n  --paper:#FFFFFF;\n  --graphite:#333333;\n  --amber:#C8801F;\n  --sage:#6E7F6A;\n  --base-font:1rem;\n}\n*{box-sizing:border-box;margin:0;padding:0;}\nhtml{font-size:100%;}\nbody{\n  font-family:'Inter',sans-serif;\n  background:var(--paper);\n  color:var(--graphite);\n  line-height:1.6;\n  padding:0 1rem;\n}\nheader{\n  display:flex;\n  justify-content:space-between;\n  align-items:center;\n  padding:1rem 0;\n}\nnav a{\n  color:var(--ink);\n  text-decoration:none;\n  margin:0 .5rem;\n  font-weight:500;\n}\nnav a:hover,nav a:focus{color:var(--amber);}\nh1,h2{\n  font-family:'Instrument Serif',serif;\n  color:var(--ink);\n}\nh1{font-size:2.5rem;margin-bottom:.5rem;}\nh2{font-size:2rem;margin-top:2rem;margin-bottom:1rem;}\nsection{max-width:800px;margin:0 auto;padding:2rem 0;}\n.hero{text-align:center;}\n.hero p{font-size:1.125rem;margin-top:.5rem;}\n.button{\n  display:inline-block;\n  background:var(--amber);\n  color:var(--paper);\n  padding:.75rem 1.5rem;\n  border:none;\n  border-radius:4px;\n  text-decoration:none;\n  font-weight:600;\n  cursor:pointer;\n}\n.button:hover,.button:focus{background:var(--sage);}\n.task-list{list-style:none;margin-top:1rem;}\n.task-item{\n  background:var(--paper);\n  border:1px solid var(--graphite);\n  padding:.75rem 1rem;\n  margin-bottom:.5rem;\n  display:flex;\n  justify-content:space-between;\n  align-items:center;\n}\n.task-item button{\n  background:none;\n  border:none;\n  color:var(--amber);\n  cursor:pointer;\n  font-size:1rem;\n}\n.task-item button:hover,.task-item button:focus{color:var(--sage);}\nform{display:flex;margin-top:1rem;}\nform input{\n  flex:1;\n  padding:.5rem;\n  border:1px solid var(--graphite);\n  border-radius:4px 0 0 4px;\n}\nform button{\n  background:var(--amber);\n  color:var(--paper);\n  border:none;\n  padding:.5rem 1rem;\n  border-radius:0 4px 4px 0;\n  cursor:pointer;\n}\nform button:hover,form button:focus{background:var(--sage);}\nfooter{text-align:center;padding:2rem 0;font-size:.875rem;color:var(--graphite);}\n:focus-visible{outline:2px solid var(--amber);outline-offset:2px;}\n.visually-hidden{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);border:0;}\nblockquote{margin:1rem 0;padding-left:1rem;border-left:4px solid var(--amber);font-style:italic;color:var(--graphite);}\nblockquote cite{display:block;margin-top:.5rem;font-style:normal;font-weight:600;color:var(--ink);}\n@media(max-width:600px){h1{font-size:2rem;}}\n</style>\n</head>\n<body>\n<header>\n  <h1>Soloist</h1>\n  <nav aria-label=\"Main navigation\">\n    <a href=\"#dashboard\">Dashboard</a>\n    <a href=\"#backlog\">Backlog</a>\n    <a href=\"#pricing\">Pricing</a>\n    <a href=\"#settings\">Settings</a>\n  </nav>\n</header>\n\n<main>\n  <section class=\"hero\" id=\"hero\">\n    <h1>What are you shipping tonight?</h1>\n    <p>Your active queue is clear. Add a new task or pick one from your backlog to get started.</p>\n    <a href=\"#tasks\" class=\"button\">Add a Task</a>\n  </section>\n\n  <section id=\"tasks\">\n    <h2>Active Tasks</h2>\n    <ul class=\"task-list\" id=\"taskList\">\n      <li class=\"task-item\"><span>Draft API spec for onboarding flow</span><button aria-label=\"Remove task\">✕</button></li>\n      <li class=\"task-item\"><span>Design landing page mockup</span><button aria-label=\"Remove task\">✕</button></li>\n      <li class=\"task-item\"><span>Write unit tests for auth module</span><button aria-label=\"Remove task\">✕</button></li>\n    </ul>\n    <form id=\"taskForm\" aria-label=\"Add new task\">\n      <label for=\"newTask\" class=\"visually-hidden\">New task</label>\n      <input type=\"text\" id=\"newTask\" placeholder=\"New task…\" required>\n      <button type=\"submit\">Add</button>\n    </form>\n  </section>\n\n  <section id=\"testimonials\">\n    <h2>What developers say</h2>\n    <blockquote>\n      <p>Soloist turned my chaotic to‑do list into a single, clear view. I ship faster and sleep better.</p>\n      <cite>— Alex Rivera, Indie Game Developer</cite>\n    </blockquote>\n    <blockquote>\n      <p>The minimalist UI lets me focus on code, not on fiddling with settings.</p>\n      <cite>— Priya Patel, Solo SaaS Founder</cite>\n    </blockquote>\n  </section>\n</main>\n\n<footer>\n  <p>© 2026 Soloist. Crafted for solo developers.</p>\n</footer>\n\n<script>\n(() => {\n  const taskList = document.getElementById('taskList');\n  const form = document.getElementById('taskForm');\n  const input = document.getElementById('newTask');\n\n  const addTask = (text) => {\n    const li = document.createElement('li');\n    li.className = 'task-item';\n    const span = document.createElement('span');\n    span.textContent = text;\n    const btn = document.createElement('button');\n    btn.setAttribute('aria-label','Remove task');\n    btn.textContent = '✕';\n    btn.addEventListener('click',()=>li.remove());\n    li.append(span, btn);\n    taskList.appendChild(li);\n  };\n\n  form.addEventListener('submit',e=>{\n    e.preventDefault();\n    const txt = input.value.trim();\n    if(txt){addTask(txt); input.value='';}\n  });\n\n  // Keyboard‑first entry: press \"n\" to focus the input\n  document.addEventListener('keydown',e=>{\n    if(e.key==='n' && !e.ctrlKey && !e.metaKey && !e.altKey){\n      e.preventDefault();\n      input.focus();\n    }\n  });\n})();\n</script>\n</body>\n</html>";
